from math import gcd


def fraction(numerator, denominator):
    if denominator == 0:
        return "-"
    if denominator < 0:
        numerator = -numerator
        denominator = -denominator
    divisor = gcd(abs(numerator), denominator)
    return f"{numerator // divisor}/{denominator // divisor}"


def confusion_matrix(count):
    return [[0] * count for _ in range(count)]


def accumulate_confusion(matrix, truth, prediction):
    for actual, predicted in zip(truth, prediction):
        matrix[actual][predicted] += 1


def correct_count(truth, prediction):
    return sum(actual == predicted for actual, predicted in zip(truth, prediction))


def matrix_lines(states, matrix):
    width = max(len(str(value)) for row in matrix for value in row)
    lines = [" " + "".join(f" {state:>{width}}" for state in states)]
    for state, row in zip(states, matrix):
        lines.append(state + "".join(f" {value:>{width}}" for value in row))
    return lines


def metric_lines(states, matrix):
    count = len(states)
    rows = [sum(row) for row in matrix]
    columns = [sum(matrix[row][column] for row in range(count)) for column in range(count)]
    total = sum(rows)
    correct = sum(matrix[state][state] for state in range(count))
    expected = sum(rows[state] * columns[state] for state in range(count))
    lines = [
        f"ACCURACY {fraction(correct, total)}",
        f"KAPPA {fraction(total * correct - expected, total * total - expected)}",
    ]
    for state, name in enumerate(states):
        true_positive = matrix[state][state]
        precision = fraction(true_positive, columns[state])
        recall = fraction(true_positive, rows[state])
        f1 = fraction(2 * true_positive, columns[state] + rows[state])
        lines.append(f"STATE {name} precision {precision} recall {recall} f1 {f1}")
    return lines


def runs(path):
    if not path:
        return []
    result = []
    start = 1
    state = path[0]
    for position in range(1, len(path)):
        if path[position] != state:
            result.append((state, start, position))
            state = path[position]
            start = position + 1
    result.append((state, start, len(path)))
    return result


def regions_overlap(first, second):
    return first[0] <= second[1] and second[0] <= first[1]


def region_counts(predicted, truth):
    matched_predicted = sum(
        any(regions_overlap(region, other) for other in truth)
        for region in predicted
    )
    matched_truth = sum(
        any(regions_overlap(region, other) for other in predicted)
        for region in truth
    )
    return len(predicted), len(truth), matched_predicted, matched_truth


def boundaries(path):
    return [
        position + 1 for position in range(1, len(path))
        if path[position - 1] != path[position]
    ]


def boundary_counts(predicted_path, true_path, tolerance):
    predicted = boundaries(predicted_path)
    truth = boundaries(true_path)
    matched_predicted = sum(
        any(abs(position - other) <= tolerance for other in truth)
        for position in predicted
    )
    matched_truth = sum(
        any(abs(position - other) <= tolerance for other in predicted)
        for position in truth
    )
    return len(predicted), len(truth), matched_predicted, matched_truth

from collections import namedtuple
from math import log


Forward = namedtuple("Forward", "values scales emissions loglik")
ForwardBackward = namedtuple(
    "ForwardBackward", "forward backward scales emissions posterior loglik"
)
Decoding = namedtuple(
    "Decoding", "viterbi viterbi_logprob posterior confidence fb"
)


def maximum_index(values):
    best = 0
    for index in range(1, len(values)):
        if values[index] > values[best]:
            best = index
    return best


def emission_factors(model, observation):
    if observation == -1:
        return [1.0] * len(model.states)
    return [row[observation] for row in model.emission]


def log_emission_factors(model, observation):
    if observation == -1:
        return [0.0] * len(model.states)
    return [log(row[observation]) for row in model.emission]


def scaled_forward(model, observations):
    count = len(model.states)
    emissions = [emission_factors(model, symbol) for symbol in observations]
    values = []
    scales = []
    loglik = 0.0
    for position, factors in enumerate(emissions):
        unscaled = []
        for state in range(count):
            if position == 0:
                value = model.initial[state] * factors[state]
            else:
                total = 0.0
                for previous in range(count):
                    total += values[position - 1][previous] * model.transition[previous][state]
                value = total * factors[state]
            unscaled.append(value)
        scale = 0.0
        for value in unscaled:
            scale += value
        scales.append(scale)
        values.append([value / scale for value in unscaled])
        loglik += log(scale)
    return Forward(values, scales, emissions, loglik)


def forward_backward(model, observations):
    forward = scaled_forward(model, observations)
    count = len(model.states)
    length = len(observations)
    backward = [[0.0] * count for _ in observations]
    backward[-1] = [1.0] * count
    for position in range(length - 2, -1, -1):
        for state in range(count):
            total = 0.0
            for following in range(count):
                total += (
                    model.transition[state][following]
                    * forward.emissions[position + 1][following]
                    * backward[position + 1][following]
                )
            backward[position][state] = total / forward.scales[position + 1]
    posterior = [
        [forward.values[t][state] * backward[t][state] for state in range(count)]
        for t in range(length)
    ]
    return ForwardBackward(
        forward.values, backward, forward.scales, forward.emissions,
        posterior, forward.loglik,
    )


def posterior_transition(model, result, position, state, following):
    return (
        result.forward[position][state]
        * model.transition[state][following]
        * result.emissions[position + 1][following]
        * result.backward[position + 1][following]
        / result.scales[position + 1]
    )


def viterbi(model, observations):
    count = len(model.states)
    transitions = [[log(value) for value in row] for row in model.transition]
    factors = log_emission_factors(model, observations[0])
    scores = [log(model.initial[state]) + factors[state] for state in range(count)]
    predecessors = [[0] * count]
    for observation in observations[1:]:
        factors = log_emission_factors(model, observation)
        next_scores = []
        previous_states = []
        for state in range(count):
            candidates = [
                scores[previous] + transitions[previous][state]
                for previous in range(count)
            ]
            previous = maximum_index(candidates)
            previous_states.append(previous)
            next_scores.append(candidates[previous] + factors[state])
        predecessors.append(previous_states)
        scores = next_scores
    path = [0] * len(observations)
    path[-1] = maximum_index(scores)
    logprob = scores[path[-1]]
    for position in range(len(observations) - 1, 0, -1):
        path[position - 1] = predecessors[position][path[position]]
    return path, logprob


def decode(model, observations):
    fb = forward_backward(model, observations)
    path, logprob = viterbi(model, observations)
    posterior = [maximum_index(row) for row in fb.posterior]
    confidence = [row[state] for row, state in zip(fb.posterior, posterior)]
    return Decoding(path, logprob, posterior, confidence, fb)

class MINSTD:
    def __init__(self, seed):
        self.state = seed

    def random(self):
        self.state = (48271 * self.state) % 2147483647
        return self.state / 2147483647


def draw(weights, generator):
    total = 0.0
    for weight in weights:
        total += weight
    threshold = generator.random() * total
    cumulative = 0.0
    for index, weight in enumerate(weights):
        cumulative += weight
        if threshold < cumulative:
            return index
    return len(weights) - 1


def synthetic_sequence(model, length, generator):
    states = []
    observations = []
    for position in range(length):
        weights = model.initial if position == 0 else model.transition[states[-1]]
        state = draw(weights, generator)
        symbol = draw(model.emission[state], generator)
        states.append(state)
        observations.append(symbol)
    return states, observations


def posterior_path(model, forward, generator):
    path = [0] * len(forward)
    path[-1] = draw(forward[-1], generator)
    for position in range(len(forward) - 2, -1, -1):
        following = path[position + 1]
        weights = [
            forward[position][state] * model.transition[state][following]
            for state in range(len(model.states))
        ]
        path[position] = draw(weights, generator)
    return path

from inference import forward_backward, posterior_transition, scaled_forward
from model_io import Model


def smoothed_model(template, name, initial, transition, emission, alpha):
    return Model(
        name, template.states, template.symbols, template.missing,
        [value + alpha for value in initial],
        [[value + alpha for value in row] for row in transition],
        [[value + alpha for value in row] for row in emission],
    )


def baum_welch_step(model, sequences, pseudocount):
    count = len(model.states)
    initial = [0.0] * count
    transition = [[0.0] * count for _ in range(count)]
    emission = [[0.0] * len(model.symbols) for _ in range(count)]
    for observations in sequences:
        result = forward_backward(model, observations)
        for state in range(count):
            initial[state] += result.posterior[0][state]
        for position, observation in enumerate(observations):
            for state in range(count):
                if observation != -1:
                    emission[state][observation] += result.posterior[position][state]
                if position + 1 < len(observations):
                    for following in range(count):
                        transition[state][following] += posterior_transition(
                            model, result, position, state, following
                        )
    return smoothed_model(
        model, "BAUM_WELCH", initial, transition, emission, pseudocount
    )


def estimate_by_counting(template, pairs, alpha, name="SUPERVISED"):
    count = len(template.states)
    initial = [0] * count
    transition = [[0] * count for _ in range(count)]
    emission = [[0] * len(template.symbols) for _ in range(count)]
    for observations, path in pairs:
        initial[path[0]] += 1
        for position, state in enumerate(path):
            observation = observations[position]
            if observation != -1:
                emission[state][observation] += 1
            if position + 1 < len(path):
                transition[state][path[position + 1]] += 1
    return smoothed_model(template, name, initial, transition, emission, alpha)


def total_loglik(model, sequences):
    total = 0.0
    for observations in sequences:
        total += scaled_forward(model, observations).loglik
    return total
